def save_json(path,content): path.write_text(json.dumps(content,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
# Case source quality is not equivalent to financial audit, or causal AI attribution.
for c in CASES:
    source_info=SOURCES[c['source']]
    c['evidence_tier'] = ('D｜匿名或化名报道' if ('匿名' in c['name'] or '化名' in c['name']) else
                           'B｜平台具名案例' if ('官方' in source_info[3] or '官方' in source_info[0]) else
                           'C｜媒体具名报道')
    c['ai_disclosed'] = ('未披露' not in c['ai'] and '未将此案例' not in c['ai'])
    c['profit_disclosed'] = False

for k,v in [('cases.json',CASES),('chapters.json',CHAPTERS),('prompts.json',PROMPTS),('routes.json',ROUTES),('plan30.json',PLANS),('sources.json',[dict(id=k,title=v[0],url=v[1],date=v[2],kind=v[3],limits=v[4]) for k,v in SOURCES.items()])]: save_json(D/k,v)
# Evidence ledger for readers who want to audit cases in Excel / Google Sheets.
with (D/'cases.csv').open('w',encoding='utf-8-sig',newline='') as f:
    w=csv.writer(f)
    w.writerow(['案例ID','名称','平台','商业模式','业绩披露（非利润）','时间','做法','AI使用与归因','是否披露AI','净利润是否披露','证据等级','可借鉴动作','无法确认项','来源类型','来源名称','原始URL'])
    for c in CASES:
        source_info=SOURCES[c['source']]
        w.writerow([c['id'],c['name'],c['platform'],c['model'],c['result'],c['period'],c['play'],c['ai'],c['ai_disclosed'],c['profit_disclosed'],c['evidence_tier'],c['takeaway'],c['caution'],source_info[3],source_info[0],source_info[1]])

# Github-readable catalog, independent of the interactive site.
lines=['# 37个中国内容电商实战案例｜证据账本','', '> 资料复核：2026-11-05。所有业绩为来源披露，不能当作净利润或AI因果结果。匿名/化名案例单独标为D级。','', '| ID | 商家 / 案例 | 平台 | 来源披露业绩（非利润） | AI证据 | 证据等级 | 原文 |', '|---|---|---|---|---|---|---|']
for c in CASES:
    source_info=SOURCES[c['source']]
    esc=lambda x: str(x).replace('|','/').replace('\n',' ')
    lines.append(f"| {c['id']} | [{esc(c['name'])}](site/cases/{c['id']}.html) | {esc(c['platform'])} | {esc(c['result'])} | {'有披露，不代表归因' if c['ai_disclosed'] else '未披露'} | {esc(c['evidence_tier'])} | [原文]({source_info[1]}) |")
lines += ['','**审计口径**：B＝平台具名，C＝媒体具名，D＝匿名或化名。该分类评估来源可追溯性，不代表财务真实性已被独立审计。所有案例均无可独立复核净利润数据；具体打法和限制请点名称打开独立案例页。','']
(ROOT/'CASEBOOK.md').write_text('\n'.join(lines),encoding='utf-8')

for name,headers in TEMPLATE_HEADERS.items():
    with (ROOT/'templates'/name).open('w',encoding='utf-8-sig',newline='') as f: csv.writer(f).writerow(headers)

for ch in CHAPTERS:
    body=f'''# {ch['id']}｜{ch['title']}\n\n> 阶段：{ch['phase']}　预计：{ch['time']}　目标：{ch['goal']}\n\n## 先理解\n{ch['core']}\n\n## 跟着做\n'''
    for n,s in enumerate(ch['steps'],1):body+=f'\n{n}. **步骤 {n}**：{s}\n   - 产出证据：记录操作时间、原始资料与截图/链接，写入 `worklogs/{ch["id"]}.md`。\n'
    body+=f'''\n## 验收标准\n{ch['accept']}\n\n## 做不下去怎么办\n{ch['limit']} 若目前没有权限、样品或真实数据，将该项标记为“阻塞”，保留原因与下一次验证日期，先完成不需权限的模拟操作，不得假装成交。\n\n## 反方审核\n假设这一步毫无效果：确认你是否有真实需求证据、实际支付和退货数据、以及可以复查的原始链接。\n\n## 输出文件\n- `{ch['id']}.md` 执行日志\n- 附图或后台导出数据（自行存放，不要上传隐私/账号信息到公开仓库）\n\n## 官方入口\n'''
    for s in ch['relatedSources']:body+=f'- [{SOURCES[s][0]}]({SOURCES[s][1]})\n'
    (ROOT/'content'/f'{ch["id"]}-{ch["title"].replace("/","-").replace("：","-")}.md').write_text(body,encoding='utf-8')
for p in PROMPTS:
    (ROOT/'prompts'/f'{p["id"]}-{p["title"].replace("/","-")}.md').write_text(f'# {p["id"]} {p["title"]}\n\n## 使用前填写\n将花括号占位符替换为自己的真实输入，不知道请填“未知”。\n\n## 可复制 Prompt\n\n```text\n{p["text"]}\n```\n\n## 人工复核\n- 事实有没有来源？\n- 数字有没有口径和时间？\n- 有无虚构评价/效果/资质？\n- 发布用到AI生成内容时是否按平台功能标识？\n',encoding='utf-8')
for c in CASES:
    src=SOURCES[c['source']]
    body=f'''# {c['id']}｜{c['name']}\n\n- 平台：**{c['platform']}**；模式：{c['model']}\n- 时间：{c['period']}\n- 披露结果：{c['result']}\n- AI 归因：**{c['ai']}**\n- 来源：[{src[0]}]({src[1]})\n- 来源类型：{src[3]}\n\n## 对方做了什么\n{c['play']}。\n\n## 我们能借鉴什么\n{c['takeaway']}。\n\n## 不能直接推出的结论\n{c['caution']} 披露GMV、销售额或ROI不意味着净利润、同等预算或因果关系。\n\n## 30分钟复刻练习\n1. 选你自己的一件真实商品或一家有权合作的商户。\n2. 用手机拍下产品的一个真实卖点或消费者常见疑问。\n3. 只借鉴“{c['play'].split('+')[0].strip()}”这项动作，做一条小样片或脚本。\n4. 写下具体投入与结果证据；没有数据就记录未知，不填案例的大品牌业绩。\n\n## 证据审计\n- 原始网址：{src[1]}\n- 披露日期/时间：{c['period']}\n- 业绩披露方：{src[3]}\n- 结果口径：{c['result']}\n- 是否确认 AI 因果：否。\n- 最近资料复核：2026-11-05（来源页检索，非财务审计）\n'''
    (ROOT/'research'/f'{c["id"]}-{c["name"].replace("/","-").replace("×","-")}.md').write_text(body,encoding='utf-8')

print('generated',len(CASES),'cases',len(CHAPTERS),'chapters',len(PROMPTS),'prompts',len(PLANS),'days',len(SOURCES),'sources',len(TEMPLATE_HEADERS),'templates')
